"use client";
import React, { useEffect, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faCalendarCheck,
  faComputerMouse,
  faCreditCard,
} from "@fortawesome/free-solid-svg-icons";
import Reviews from "../about-us/reviews";
import Destinations from "../after-your-booking/destinations";

const tabs = [
  { id: "cancellation", label: "Operator Cancellation Guidelines" },
  { id: "flexible", label: "Flexible Booking Choices" },
  { id: "insurance", label: "Comprehensive Travel Insurance" },
  { id: "faq", label: "FAQ" },
];

const flexibleCards = [
  {
    icon: faCalendarCheck,
    title: "Modify your travel dates",
    body: "We understand that plans can change, so many of our operators offer the flexibility to select a new departure date.",
  },
  {
    icon: faComputerMouse,
    title: "Pick an alternative adventure",
    body: "If your new departure dates or chosen tour no longer fit your plans, some operators offer the option to book a different tour.",
  },
  {
    icon: faCreditCard,
    title: "Get travel credit if your plans change",
    body: "Unable to choose new dates or a tour at the time of cancellation? Some operators provide credit for a future adventure.",
  },
];

const faqs: { q: string; a: React.ReactNode }[] = [
  {
    q: "What is the cancellation policy for TravelShop Booking?",
    a: "Keep in mind that tours on TravelShop Booking are managed by operators (the companies organizing your tour), and each operator has its own cancellation policy.",
  },
  {
    q: "How do I make changes to my booking?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-2">
          Visit your tour&apos;s Booking Conversation Page and select
          &ldquo;Modify Booking&rdquo; to:
        </p>
        <ul className="tw-m-0 tw-pl-5 tw-space-y-1">
          <li>Change tour dates</li>
          <li>Select a different tour (with the same operator)</li>
          <li>
            Receive Credit for Future Tours: apply credit to a future trip with
            the same operator.
          </li>
          <li>
            Cancel your tour: full refunds are not guaranteed, and fees may
            apply as per your operator&apos;s terms. Cancellations must be
            submitted in writing via the &ldquo;Modify Booking&rdquo; option.
          </li>
        </ul>
        <p className="tw-mt-2 tw-mb-0">Fees may apply.</p>
      </>
    ),
  },
  {
    q: "How do I find out if the tour includes flexible booking options?",
    a: (
      <>
        The Peace of Mind Program is available only for adventures offered by
        select operators. Check the &quot;Your{" "}
        <a
          href="/cancellation-policy/peace-mind"
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9]"
        >
          Peace of Mind
        </a>{" "}
        Options&quot; section on the Tour Detail Page. Alternatively, if
        you&apos;ve already booked, you can{" "}
        <a
          href="/contact-us"
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9]"
        >
          contact us
        </a>{" "}
        through your Booking Conversation Page.
      </>
    ),
  },
  {
    q: "How do I delay my booking and get Credit for Future Tours?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-2">
          <a
            href="https://travelshopbooking.com/"
            target="_blank"
            rel="noopener noreferrer"
            className="tw-font-semibold tw-text-[#854ec9]"
          >
            Log in to your account
          </a>{" "}
          and click on your booking to access your Booking Conversation Page.
          Select the &ldquo;Modify Booking&rdquo; option and follow the steps.
          If you need assistance, don&apos;t hesitate to{" "}
          <a
            href="/contact-us"
            target="_blank"
            rel="noopener noreferrer"
            className="tw-font-semibold tw-text-[#854ec9]"
          >
            contact our Travel Experts
          </a>{" "}
          — we&apos;re available 24/7!
        </p>
        <p className="tw-mt-0 tw-mb-0">
          <b className="tw-text-[#14101c]">Important:</b> if you postpone your
          booking, the Credit for Future Tours will only be valid with the
          operator you originally booked.
        </p>
      </>
    ),
  },
  {
    q: "If I convert to Credit before my final payment is due, what amount will I receive credit for?",
    a: "If you've made only the initial payment (due at booking) and haven't paid the final amount yet, you'll receive credit for the initial payment. The final payment will not be charged.",
  },
  {
    q: "If I convert to Credit for Future Tours, will I still be charged future installments?",
    a: "If you chose to pay in installments, you'll receive credit for the payments made up until the cancellation. You won't be charged for any future installments. Depending on your adventure's date, cancellation fees may apply based on the operator's policy and the TravelShop Booking Cancellation Policy.",
  },
  {
    q: "What occurs if the operator cancels my tour?",
    a: "If the operator cancels your trip for any reason, we'll inform you promptly via email or phone. You can also check for updates from both TravelShop Booking and your operator anytime on your Booking Conversation Page.",
  },
  {
    q: "Can the operator modify my tour?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-2">
          Yes, there are two possible scenarios:
        </p>
        <p className="tw-mt-0 tw-mb-2">
          <b className="tw-text-[#14101c]">Rerouting:</b> an operator may adjust
          the itinerary at any time to ensure the safety of travelers. They will
          reach out to inform you of any necessary changes.
        </p>
        <p className="tw-mt-0 tw-mb-0">
          <b className="tw-text-[#14101c]">Suspension:</b> operators may suspend
          your upcoming departure if there are safety concerns, and will contact
          you with alternative options.
        </p>
      </>
    ),
  },
];

const CancellationPolicy = () => {
  const [active, setActive] = useState(tabs[0].id);

  useEffect(() => {
    const sections = tabs
      .map((t) => document.getElementById(t.id))
      .filter((el): el is HTMLElement => el !== null);

    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) setActive(visible.target.id);
      },
      { rootMargin: "-40% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
    );

    sections.forEach((s) => observer.observe(s));
    return () => observer.disconnect();
  }, []);

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/capa.webp')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.5) 0%, rgba(20,16,28,0.6) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Cancellation Policy
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Tour Modifications &amp; Rescheduling
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Flexible booking options, trip protection and clear answers — so
              you can book with confidence and peace of mind.
            </p>
          </div>
        </div>
      </section>

      {/* Sticky tab nav */}
      <div className="tw-sticky tw-top-0 tw-z-30 tw-bg-white/90 tw-backdrop-blur tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-4 md:tw-px-8">
          <nav
            className="tw-flex tw-gap-1.5 tw-overflow-x-auto tw-py-3"
            style={{ scrollbarWidth: "none" }}
          >
            {tabs.map((tab) => (
              <a
                key={tab.id}
                href={`#${tab.id}`}
                aria-current={active === tab.id ? "true" : undefined}
                className={`tw-whitespace-nowrap tw-rounded-full tw-px-4 tw-py-2 tw-text-[14px] tw-font-semibold tw-no-underline tw-transition-colors ${
                  active === tab.id
                    ? "tw-bg-[#854ec9] tw-text-white"
                    : "tw-text-[#5d556c] hover:tw-bg-[#faf9fc] hover:tw-text-[#14101c]"
                }`}
              >
                {tab.label}
              </a>
            ))}
          </nav>
        </div>
      </div>

      {/* Operator cancellation */}
      <section
        id="cancellation"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Cancellation Policy of Your Operator
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Each operator has its own cancellation policy, and with over
                2,500 operators, it can be a bit overwhelming. But we believe in
                transparency. You can find the cancellation policy for each
                operator in the &quot;Good to Know&quot; section of the Tour
                Detail Page, on the checkout page when booking, and on your
                Booking Conversation Page after completing your booking.
              </p>
              <p className="tw-mt-3 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Click the link below to learn how to cancel your tour, or check
                out our FAQ section further down the page for more information.
              </p>
              <a
                href="/help-center"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-2 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Learn More <span aria-hidden="true">→</span>
              </a>
            </div>
            <div>
              <img
                src="/images/handshake.jpg"
                alt="Operator agreement"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Flexible */}
      <section
        id="flexible"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-max-w-[820px]">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Flexible Reservation Choices
            </h2>
            <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
              At TravelShop Booking, we aim to give travelers peace of mind when
              booking, which is why we encourage operators to provide flexible
              booking options through our{" "}
              <a
                href="/cancellation-policy/peace-mind"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-font-semibold tw-text-[#854ec9]"
              >
                Peace of Mind
              </a>{" "}
              program. This allows you to:
            </p>
          </div>
          <div className="tw-mt-8 tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {flexibleCards.map((card) => (
              <div
                key={card.title}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
              >
                <div className="tw-flex tw-h-14 tw-w-14 tw-items-center tw-justify-center tw-rounded-2xl tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                  <FontAwesomeIcon icon={card.icon} className="tw-text-2xl" />
                </div>
                <h3 className="tw-mt-4 tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-m-0">
                  {card.title}
                </h3>
                <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                  {card.body}
                </p>
              </div>
            ))}
          </div>
          <div className="tw-mt-8 tw-max-w-[820px]">
            <h3 className="tw-text-[16px] tw-font-bold tw-text-[#14101c]">
              How can I find details about my flexible booking options?
            </h3>
            <p className="tw-mt-2 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
              Check the &quot;Your Peace of Mind Options&quot; section on the
              Tour Detail Page, located just below the &quot;What&apos;s
              Included&quot; section.
            </p>
            <p className="tw-mt-2 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
              <b className="tw-text-[#14101c]">Important:</b> keep in mind that
              the Credit for Future Tours is only valid with the operator you
              initially booked.
            </p>
          </div>
        </div>
      </section>

      {/* Insurance */}
      <section id="insurance" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/olds.jpg"
                alt="Trip protection"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Trip Protection &amp; Insurance
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Travel can be unpredictable. By adding travel insurance to your
                booking, you&apos;ll be covered for medical emergencies, trip
                cancellations, lost baggage, and more. You can view your
                personalized travel insurance quote during checkout or find more
                details by following the link below.
              </p>
              <a
                href="/cancellation-policy/travel-insurance"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-2 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Learn More <span aria-hidden="true">→</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section
        id="faq"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Common Questions &amp; Answers
            </h2>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-2 tw-gap-5 lg:tw-gap-6">
            {faqs.map((faq) => (
              <div
                key={faq.q}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6"
              >
                <h3 className="tw-text-[16px] tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-3">
                  {faq.q}
                </h3>
                <div className="tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
                  {faq.a}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <Reviews />

      <Destinations />
    </main>
  );
};

export default CancellationPolicy;
